/**
 * pages/Attendance.js
 * Check-in / Check-out panel with geolocation + monthly history table.
 */
import { useState, useEffect, useCallback } from 'react';
import { useAuth } from '../context/AuthContext';
import Spinner from '../components/common/Spinner';
import Pagination from '../components/common/Pagination';
import { useToast } from '../components/common/Toast';
import { getTodayStatus, checkIn, checkOut, getAttendanceHistory, getEmployees } from '../services/api';

export default function Attendance() {
  const { isAdmin } = useAuth();
  const toast = useToast();

  const [status,   setStatus]   = useState(null);
  const [history,  setHistory]  = useState([]);
  const [total,    setTotal]    = useState(0);
  const [page,     setPage]     = useState(1);
  const [pages,    setPages]    = useState(1);
  const [month,    setMonth]    = useState(new Date().toISOString().slice(0, 7));
  const [empFilter, setEmpFilter] = useState('');
  const [employees, setEmployees] = useState([]);
  const [loading,  setLoading]  = useState(true);
  const [checkingIn, setCheckingIn] = useState(false);
  const [geoError, setGeoError] = useState('');
  const [debugInfo, setDebugInfo] = useState(null);
  const [diag, setDiag] = useState(null);
  // eslint-disable-next-line no-unused-vars
  const [timer,    setTimer]    = useState(null); // live working hours

  useEffect(() => {
    loadStatus();
    if (isAdmin) getEmployees({ per_page: 200 }).then((r) => setEmployees(r.data.employees || []));
    // eslint-disable-next-line
  }, []);

  useEffect(() => { loadHistory(); }, [page, month, empFilter]); // eslint-disable-line

  // Live timer when checked in
  useEffect(() => {
    if (status?.status === 'checked_in' && status?.check_in) {
      const id = setInterval(() => setTimer(Date.now()), 1000);
      return () => clearInterval(id);
    }
  }, [status]);

  const loadStatus = async () => {
    try { const { data } = await getTodayStatus(); setStatus(data); }
    catch {}
  };

  const loadHistory = useCallback(async () => {
    setLoading(true);
    try {
      const params = { page, per_page: 20 };
      if (month) params.month = month;
      if (isAdmin && empFilter) params.employee_id = empFilter;
      const { data } = await getAttendanceHistory(params);
      setHistory(data.records);
      setTotal(data.total);
      setPages(data.pages);
    } catch { toast.error('Failed to load attendance history.'); }
    finally { setLoading(false); }
    // eslint-disable-next-line
  }, [page, month, empFilter, isAdmin]);

  const handleCheckIn = () => {
    setGeoError('');
    setDebugInfo(null);
    setCheckingIn(true);
    if (!navigator.geolocation) {
      setGeoError('Geolocation is not supported by your browser.');
      setCheckingIn(false);
      return;
    }
    navigator.geolocation.getCurrentPosition(
      async (pos) => {
        try {
          await checkIn({ latitude: pos.coords.latitude, longitude: pos.coords.longitude });
          toast.success('✅ Checked in successfully!');
          await loadStatus();
          loadHistory();
        } catch (err) {
          const msg = err.response?.data?.error || 'Check-in failed.';
          setGeoError(msg);
          if (err.response?.data?.debug_info) {
            setDebugInfo(err.response.data.debug_info);
          }
          toast.error(msg);
        } finally { setCheckingIn(false); }
      },
      (err) => {
        const msg = err.code === 1
          ? 'Location permission denied. Please allow location access and try again.'
          : 'Could not determine your location. Please try again.';
        setGeoError(msg);
        toast.error(msg);
        setCheckingIn(false);
      },
      { enableHighAccuracy: true, timeout: 10000 }
    );
  };

  const runDiagnostics = () => {
    if (!navigator.geolocation) {
      toast.error('Geolocation is not supported.');
      return;
    }
    navigator.geolocation.getCurrentPosition(
      (pos) => {
        const lat = pos.coords.latitude;
        const lon = pos.coords.longitude;
        const acc = pos.coords.accuracy;
        const time = new Date(pos.timestamp).toLocaleString();

        const getDistance = (lat1, lon1, lat2, lon2) => {
          const R = 6371000;
          const dLat = (lat2 - lat1) * Math.PI / 180;
          const dLon = (lon2 - lon1) * Math.PI / 180;
          const a = Math.sin(dLat / 2) * Math.sin(dLat / 2) +
                    mathCos(lat1) * mathCos(lat2) *
                    Math.sin(dLon / 2) * Math.sin(dLon / 2);

          function mathCos(deg) { return Math.cos(deg * Math.PI / 180); }
          const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
          return R * c;
        };

        const officeLat = 28.390583;
        const officeLon = 77.064722;

        setDiag({
          latitude: lat,
          longitude: lon,
          accuracy: acc,
          timestamp: time,
          officeLatitude: officeLat,
          officeLongitude: officeLon,
          distance: getDistance(lat, lon, officeLat, officeLon)
        });
        toast.info(`Diagnostics completed: Accuracy = ${acc.toFixed(1)}m`);
      },
      (err) => {
        toast.error(`Diagnostics failed: ${err.message}`);
      },
      { enableHighAccuracy: true, timeout: 10000 }
    );
  };

  const handleCheckOut = async () => {
    setCheckingIn(true);
    try {
      const { data } = await checkOut();
      toast.success(`✅ Checked out. Working hours: ${data.working_hours?.toFixed(2)}h`);
      await loadStatus();
      loadHistory();
    } catch (err) {
      toast.error(err.response?.data?.error || 'Check-out failed.');
    } finally { setCheckingIn(false); }
  };

  const getLiveHours = () => {
    if (!status?.check_in || status.status !== 'checked_in') return null;
    const diff = (Date.now() - new Date(status.check_in).getTime()) / 1000;
    const h = Math.floor(diff / 3600);
    const m = Math.floor((diff % 3600) / 60);
    const s = Math.floor(diff % 60);
    return `${String(h).padStart(2, '0')}:${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}`;
  };

  const dotClass =
    status?.status === 'checked_in'  ? 'checked-in'  :
    status?.status === 'checked_out' ? 'checked-out' : 'not-checked';

  const dotEmoji =
    status?.status === 'checked_in'  ? '✅' :
    status?.status === 'checked_out' ? '🏁' : '⏰';

  return (
    <div className="fade-in">
      <div className="page-header">
        <div className="page-header-left">
          <h2>Attendance</h2>
          <p>{new Date().toLocaleDateString('en-IN', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}</p>
        </div>
      </div>

      {/* Check-in Panel (All users) */}
      <div className="card" style={{ marginBottom: 24 }}>
        <div className="checkin-panel">
          <div className={`checkin-status-dot ${dotClass}`}>{dotEmoji}</div>

          <div style={{ textAlign: 'center' }}>
            <h3 style={{ fontSize: 20, fontWeight: 700, color: 'var(--text-primary)' }}>
              {status?.status === 'checked_in'  ? 'You are checked in' :
               status?.status === 'checked_out' ? 'Work day complete'  : 'Not checked in yet'}
            </h3>
            {status?.check_in && (
              <p style={{ color: 'var(--text-muted)', marginTop: 6 }}>
                Check-in: {new Date(status.check_in).toLocaleTimeString()}
                {status.check_out && ` · Check-out: ${new Date(status.check_out).toLocaleTimeString()}`}
              </p>
            )}
            {status?.check_in && (
              <div className="alert alert-info" style={{ marginTop: 10, marginBottom: 10, padding: '8px 12px', fontSize: 13, display: 'inline-flex' }}>
                ℹ️ You have already checked in for today.
              </div>
            )}
            {status?.status === 'checked_in' && getLiveHours() && (
              <div style={{
                fontSize: 38, fontWeight: 800, color: 'var(--success)',
                fontFamily: 'monospace', marginTop: 8,
              }}>
                {getLiveHours()}
              </div>
            )}
            {status?.working_hours > 0 && status?.status === 'checked_out' && (
              <div style={{ fontSize: 26, fontWeight: 800, color: 'var(--info)', marginTop: 8 }}>
                {status.working_hours.toFixed(2)}h total
              </div>
            )}
          </div>

          {geoError && (
            <div className="alert alert-error" style={{ width: '100%', maxWidth: 420 }}>{geoError}</div>
          )}

          {debugInfo && (
            <div className="card" style={{ width: '100%', maxWidth: 420, padding: 16, marginTop: 12, fontSize: 13, textAlign: 'left', background: 'var(--bg-elevated)', border: '1px dashed var(--border)' }}>
              <strong style={{ color: 'var(--warning)', display: 'block', marginBottom: 8 }}>📍 Geofencing Debug Info:</strong>
              <div style={{ display: 'flex', flexDirection: 'column', gap: 4 }}>
                <div><strong>Your Latitude:</strong> {debugInfo.user_latitude}</div>
                <div><strong>Your Longitude:</strong> {debugInfo.user_longitude}</div>
                <div><strong>Office Latitude:</strong> {debugInfo.office_latitude}</div>
                <div><strong>Office Longitude:</strong> {debugInfo.office_longitude}</div>
                <div><strong>Distance:</strong> {debugInfo.distance_meters?.toFixed(2)} meters</div>
              </div>
            </div>
          )}


          {diag && (
            <div className="card" style={{ width: '100%', maxWidth: 420, padding: 16, marginTop: 12, fontSize: 13, textAlign: 'left', background: 'var(--bg-elevated)', border: '1px solid var(--border)' }}>
              <strong style={{ color: 'var(--info)', display: 'block', marginBottom: 8 }}>📡 Geolocation Diagnostics:</strong>
              <div style={{ display: 'flex', flexDirection: 'column', gap: 4 }}>
                <div><strong>Browser Latitude:</strong> {diag.latitude}</div>
                <div><strong>Browser Longitude:</strong> {diag.longitude}</div>
                <div><strong>Accuracy Radius:</strong> {diag.accuracy?.toFixed(2)} meters</div>
                <div><strong>Timestamp:</strong> {diag.timestamp}</div>
                <div><strong>Office Latitude:</strong> {diag.officeLatitude}</div>
                <div><strong>Office Longitude:</strong> {diag.officeLongitude}</div>
                <div><strong>Calculated Distance:</strong> {diag.distance?.toFixed(2)} meters</div>
              </div>
            </div>
          )}

          <div style={{ display: 'flex', gap: 12, flexWrap: 'wrap', justifyContent: 'center' }}>
            {status?.status === 'not_checked_in' && (
              <button className="btn btn-success btn-lg" onClick={handleCheckIn} disabled={checkingIn}>
                {checkingIn ? '📍 Getting location…' : '📍 Check In'}
              </button>
            )}
            {status?.status === 'checked_in' && (
              <button className="btn btn-danger btn-lg" onClick={handleCheckOut} disabled={checkingIn}>
                {checkingIn ? 'Processing…' : '🏁 Check Out'}
              </button>
            )}
            <button className="btn btn-secondary" onClick={runDiagnostics}>
              🔍 Geolocation Diagnostics
            </button>
          </div>

          <p style={{ fontSize: 12, color: 'var(--text-muted)', textAlign: 'center', maxWidth: 320 }}>
            📍 Check-in requires you to be within the allowed office radius.
            Make sure location permissions are enabled in your browser.
          </p>
        </div>
      </div>

      {/* History */}
      <div className="card">
        <div className="card-header">
          <div className="card-title">📅 Attendance History</div>
        </div>

        <div className="search-filter-row" style={{ marginBottom: 16 }}>
          <div className="form-group" style={{ margin: 0 }}>
            <input type="month" className="form-control" value={month} onChange={(e) => { setMonth(e.target.value); setPage(1); }} />
          </div>
          {isAdmin && (
            <select className="form-control filter-select" value={empFilter} onChange={(e) => { setEmpFilter(e.target.value); setPage(1); }}>
              <option value="">All Employees</option>
              {employees.map((e) => <option key={e.id} value={e.id}>{e.name}</option>)}
            </select>
          )}
        </div>

        {loading ? <Spinner /> : (
          <>
            <div className="table-wrapper">
              <table>
                <thead>
                  <tr>
                    {isAdmin && <th>Employee</th>}
                    <th>Date</th>
                    <th>Check In</th>
                    <th>Check Out</th>
                    <th>Working Hours</th>
                    <th>Status</th>
                  </tr>
                </thead>
                <tbody>
                  {history.length === 0 && (
                    <tr><td colSpan={isAdmin ? 6 : 5}>
                      <div className="empty-state"><div className="empty-state-icon">📭</div><h3>No records for this period</h3></div>
                    </td></tr>
                  )}
                  {history.map((r) => {
                    const hours = r.working_hours || 0;
                    return (
                      <tr key={r.id}>
                        {isAdmin && <td style={{ fontWeight: 600 }}>{r.employee_name}</td>}
                        <td style={{ fontWeight: 600 }}>{r.date}</td>
                        <td className="td-muted">{r.check_in ? new Date(r.check_in).toLocaleTimeString() : '—'}</td>
                        <td className="td-muted">{r.check_out ? new Date(r.check_out).toLocaleTimeString() : '—'}</td>
                        <td style={{
                          fontWeight: 700,
                          color: hours >= 8 ? 'var(--success)' : hours >= 4 ? 'var(--warning)' : hours > 0 ? 'var(--danger)' : 'var(--text-muted)',
                        }}>
                          {hours > 0 ? `${hours.toFixed(2)}h` : '—'}
                        </td>
                        <td>
                          <span className={`badge ${r.check_out ? 'badge-approved' : r.check_in ? 'badge-in-progress' : 'badge-pending'}`}>
                            {r.check_out ? 'Complete' : r.check_in ? 'In Progress' : 'Absent'}
                          </span>
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
            <Pagination page={page} pages={pages} onPageChange={setPage} />
            {total > 0 && <p style={{ textAlign: 'center', fontSize: 13, color: 'var(--text-muted)', marginTop: 8 }}>{total} record{total !== 1 ? 's' : ''}</p>}
          </>
        )}
      </div>
    </div>
  );
}
